      previewRouteJSON:(t,d,m,id)=>safe(()=>previewRoute(JSON.parse(t),JSON.parse(d),m,id)),commitRouteJSON:(t,p)=>safe(()=>commitRoute(JSON.parse(t),JSON.parse(p)))};
